:host {
  --ink: #2c3e50;
  --muted: #7f8c8d;
  --accent: #00CED1;
  --warm: #FFBF00;
  --line: #ecf0f1;
  --paper: #ffffff;
  --bg: #f4f7f6;
  --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-mono: "SF Mono", Monaco, Consolas, "Liberation Mono", monospace;
  display: block;
  font-family: var(--font-main);
  color: var(--ink);
  background: var(--bg);
  padding: 2rem;
  box-sizing: border-box;
}

.chapter-container {
  max-width: 1200px;
  margin: 0 auto;
  background: var(--paper);
  border: 1px solid var(--line);
  box-shadow: 0 4px 6px rgba(0,0,0,0.05);
  border-radius: 4px;
  overflow: hidden;
}

.chapter-header {
  border-bottom: 2px solid var(--ink);
  padding: 1.5rem 2rem;
  background: var(--ink);
  color: var(--paper);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.chapter-title {
  margin: 0;
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.chapter-meta {
  font-size: 0.85rem;
  opacity: 0.8;
  font-family: var(--font-mono);
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 2rem;
  padding: 2rem;
}

@media (max-width: 900px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

/* Main Visual Area */
.main-visual {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.equation-card {
  background: #fafafa;
  border: 1px solid var(--line);
  border-left: 4px solid var(--muted);
  padding: 1.5rem;
  border-radius: 2px;
  transition: all 0.3s ease;
}

.equation-card.active {
  border-left-color: var(--accent);
  background: #f0ffff;
  box-shadow: 0 2px 8px rgba(0, 206, 209, 0.15);
}

.equation-card h3 {
  margin-top: 0;
  font-size: 1.1rem;
  color: var(--ink);
  border-bottom: 1px solid var(--line);
  padding-bottom: 0.5rem;
  margin-bottom: 1rem;
}

.text-block {
  font-size: 0.95rem;
  line-height: 1.6;
  color: #444;
  margin-bottom: 1rem;
}

.math-display {
  font-family: var(--font-mono);
  background: #fff;
  padding: 1rem;
  border: 1px solid #eee;
  text-align: center;
  font-size: 1.1rem;
  color: var(--ink);
  margin-bottom: 1rem;
  overflow-x: auto;
}

.matrix-visual {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 1rem;
}

.matrix-bracket {
  border-left: 2px solid var(--ink);
  border-right: 2px solid var(--ink);
  padding: 0.5rem 0.8rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  background: #fff;
}

.matrix-row {
  font-family: var(--font-mono);
  font-size: 1rem;
}

.matrix-label {
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* Control Panel */
.control-panel {
  background: #2c3e50;
  color: #fff;
  padding: 1.5rem;
  border-radius: 4px;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.control-panel h3 {
  margin: 0 0 1rem 0;
  font-size: 1.1rem;
  color: var(--accent);
  border-bottom: 1px solid rgba(255,255,255,0.1);
  padding-bottom: 0.5rem;
}

.stepper-controls {
  display: flex;
  gap: 1rem;
}

.step-item {
  flex: 1;
  background: rgba(255,255,255,0.05);
  padding: 0.8rem;
  border-radius: 4px;
  border: 1px solid transparent;
  cursor: default;
  transition: all 0.3s;
}

.step-item.active {
  background: rgba(0, 206, 209, 0.1);
  border-color: var(--accent);
}

.step-item.completed {
  background: rgba(0, 206, 209, 0.2);
  border-color: var(--accent);
}

.step-indicator {
  font-weight: bold;
  font-size: 0.9rem;
  margin-bottom: 0.3rem;
  color: var(--accent);
}

.step-desc {
  font-size: 0.8rem;
  color: #ccc;
}

.calculation-display {
  background: rgba(0,0,0,0.2);
  padding: 1rem;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 0.9rem;
}

.calc-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.5rem;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  padding-bottom: 0.3rem;
}

.calc-row:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.calc-row .label {
  color: #aaa;
}

.calc-row .value {
  color: var(--accent);
  font-weight: bold;
}

.action-buttons {
  display: flex;
  gap: 1rem;
}

button {
  font-family: var(--font-main);
  cursor: pointer;
  border: none;
  outline: none;
  transition: background 0.2s;
}

.btn-primary {
  flex: 2;
  background: var(--accent);
  color: #004d40;
  font-weight: bold;
  padding: 0.8rem;
  border-radius: 2px;
  font-size: 1rem;
}

.btn-primary:hover {
  background: #00bfbf;
}

.btn-primary:disabled {
  background: #555;
  color: #888;
  cursor: not-allowed;
}

.btn-secondary {
  flex: 1;
  background: transparent;
  border: 1px solid #555;
  color: #ccc;
  padding: 0.8rem;
  border-radius: 2px;
}

.btn-secondary:hover {
  border-color: #888;
  color: #fff;
}

.source-btn {
  background: transparent;
  color: var(--muted);
  border: 1px solid var(--line);
  padding: 0.4rem 0.8rem;
  font-size: 0.8rem;
  border-radius: 2px;
  margin-top: 0.5rem;
  align-self: flex-start;
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.source-btn.small {
  font-size: 0.75rem;
  padding: 0.2rem 0.5rem;
  margin-top: 0;
  align-self: flex-start;
}

/* Evidence Section */
.evidence-section {
  padding: 2rem;
  background: #fafafa;
  border-top: 1px solid var(--line);
}

.evidence-section h3 {
  margin-top: 0;
  font-size: 1.2rem;
  color: var(--ink);
  margin-bottom: 0.5rem;
}

.section-intro {
  font-size: 0.95rem;
  color: #555;
  margin-bottom: 1.5rem;
  max-width: 800px;
}

.table-wrapper {
  overflow-x: auto;
  margin-bottom: 1rem;
  border: 1px solid var(--line);
  background: #fff;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
  min-width: 600px;
}

.data-table th, .data-table td {
  padding: 0.8rem 1rem;
  text-align: right;
  border-bottom: 1px solid var(--line);
}

.data-table th {
  background: #f0f0f0;
  color: var(--ink);
  font-weight: 600;
  text-align: center;
}

.data-table td:first-child, .data-table th:first-child {
  text-align: left;
  font-weight: 600;
  color: var(--ink);
  background: #fafafa;
}

.data-table tr:hover td {
  background: #f9f9f9;
}

.table-notes {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.5;
}

.table-notes strong {
  color: var(--ink);
}

