(function() {
  const root = document.currentScript.closest('.chapter-container') || document.body;

  // State
  let currentStep = 0;
  const totalSteps = 2;

  // DOM Elements
  const btnNext = root.querySelector('#btn-next');
  const btnReset = root.querySelector('#btn-reset');
  const statusText = root.querySelector('#status-text');
  const residualVal = root.querySelector('#residual-val');
  const posVal = root.querySelector('#pos-val');
  const stepItems = root.querySelectorAll('.step-item');
  const eqCards = root.querySelectorAll('.equation-card');
  const tableBody = root.querySelector('#mse-table-body');

  // Data from runtime (simulated structure based on prompt requirements)
  // In real runtime, this comes from window.paperMindData.tables
  const mseData = [
    { id: 'ROW_A', label: 'A (SI Method)', values: { 'M = 4': '1.5768', 'M = 5': '0.1597', 'M = 6': '0.1480', 'M = 7': '0.1229', 'M = 8': '0.1164', 'M = 9': '0.1148', 'M = 10': '0.1103' } },
    { id: 'ROW_B', label: 'B (Taylor Series)', values: { 'M = 4': '0.7061', 'M = 5': '0.1460', 'M = 6': '0.1341', 'M = 7': '0.1144', 'M = 8': '0.1057', 'M = 9': '0.1034', 'M = 10': '0.09462' } },
    { id: 'ROW_C', label: 'C (Proposed)', values: { 'M = 4': '0.7282', 'M = 5': '0.1456', 'M = 6': '0.1359', 'M = 7': '0.1159', 'M = 8': '0.1077', 'M = 9': '0.1055', 'M = 10': '0.09697' } },
    { id: 'ROW_D', label: 'D (Proposed Ref)', values: { 'M = 4': '0.6986', 'M = 5': '0.1451', 'M = 6': '0.1337', 'M = 7': '0.1141', 'M = 8': '0.1055', 'M = 9': '0.1034', 'M = 10': '0.09480' } },
    { id: 'ROW_E', label: 'E (CRLB)', values: { 'M = 4': '0.6884', 'M = 5': '0.1451', 'M = 6': '0.1334', 'M = 7': '0.1143', 'M = 8': '0.1054', 'M = 9': '0.1032', 'M = 10': '0.09432' } }
  ];

  // Teaching Assumptions for Calculation
  // These are hypothetical values to demonstrate the math, not real training weights
  const teachingParams = {
    step1_residual: 0.854,
    step1_pos: '(12.4, -3.2)',
    step2_residual: 0.103,
    step2_pos: '(10.1, -2.9)'
  };

  function initTable() {
    if (!tableBody) return;
    tableBody.innerHTML = '';
    mseData.forEach(row => {
      const tr = document.createElement('tr');
      let html = `<td>${row.label}</td>`;
      for (let m = 4; m <= 10; m++) {
        const key = `M = ${m}`;
        const val = row.values[key] || '-';
        // Highlight CRLB row slightly
        const style = row.id === 'ROW_E' ? 'color: var(--accent); font-weight:bold;' : '';
        html += `<td style="${style}">${val}</td>`;
      }
      tr.innerHTML = html;
      tableBody.appendChild(tr);
    });
  }

  function updateUI() {
    // Reset classes
    stepItems.forEach(el => {
      el.classList.remove('active', 'completed');
      if (parseInt(el.dataset.step) < currentStep) {
        el.classList.add('completed');
      }
    });

    eqCards.forEach((el, idx) => {
      el.classList.remove('active');
      if (idx + 1 === currentStep) {
        el.classList.add('active');
      }
    });

    // Update Text based on Step
    if (currentStep === 0) {
      statusText.textContent = '准备就绪';
      residualVal.textContent = '-';
      posVal.textContent = '-';
      btnNext.textContent = '执行 Step 1: 无约束 WLS';
      btnNext.disabled = false;
    } else if (currentStep === 1) {
      statusText.textContent = '第一步完成 (忽略约束)';
      statusText.style.color = '#fff';
      residualVal.textContent = teachingParams.step1_residual.toFixed(3);
      posVal.textContent = teachingParams.step1_pos;
      btnNext.textContent = '执行 Step 2: 约束修正';
      btnNext.disabled = false;
    } else if (currentStep === 2) {
      statusText.textContent = '第二步完成 (应用几何约束)';
      statusText.style.color = 'var(--accent)';
      residualVal.textContent = teachingParams.step2_residual.toFixed(3);
      posVal.textContent = teachingParams.step2_pos;
      btnNext.textContent = '计算结束';
      btnNext.disabled = true;
    }

    // Highlight active step card
    const activeStepCard = stepItems[currentStep - 1];
    if (activeStepCard) activeStepCard.classList.add('active');
  }

  function handleNext() {
    if (currentStep < totalSteps) {
      currentStep++;
      updateUI();
    }
  }

  function handleReset() {
    currentStep = 0;
    updateUI();
  }

  // Event Listeners
  if (btnNext) btnNext.addEventListener('click', handleNext);
  if (btnReset) btnReset.addEventListener('click', handleReset);

  // Source Buttons Logic (Mock for visualization, actual handling by kernel)
  const sourceBtns = root.querySelectorAll('[data-source]');
  sourceBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      // Kernel handles the actual source lookup via data-source attribute
      console.log('Source request:', btn.dataset.source);
    });
  });

  // Initialize
  initTable();
  updateUI();

})();
